function solve(numCourses, prerequisites) {
  const adj = Array.from({ length: numCourses }, () => []);
  for (const [a, b] of prerequisites) adj[b].push(a);
  const state = new Array(numCourses).fill(0);
  const order = [];
  function dfs(u) {
    if (state[u] === 1) return false;
    if (state[u] === 2) return true;
    state[u] = 1;
    for (const v of adj[u]) if (!dfs(v)) return false;
    state[u] = 2;
    order.push(u);
    return true;
  }
  for (let i = 0; i < numCourses; i++) if (!dfs(i)) return [];
  return order.reverse();
}

function solve(numCourses, prerequisites) {
  const adj = Array.from({ length: numCourses }, () => []);
  const indegree = new Array(numCourses).fill(0);
  for (const [a, b] of prerequisites) { adj[b].push(a); indegree[a]++; }
  const q = [];
  for (let i = 0; i < numCourses; i++) if (indegree[i] === 0) q.push(i);
  const order = [];
  while (q.length) {
    const c = q.shift();
    order.push(c);
    for (const next of adj[c]) if (--indegree[next] === 0) q.push(next);
  }
  return order.length === numCourses ? order : [];
}

